from .objects.mosaiq_core_objects import MosaiqCoreObjects
from .objects.mosaiq_rtp_import_objects import RTP_Import
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
import time

def __find_main_window() -> bool:
    """Searches for the main RTP Import UI window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the rtp_import.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(RTP_Import.Main_Window) is not None else False

def __find_promote_plan_window() -> bool:
    """Searches for the Promote Plan dialog within the RTP Import workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the rtp_import.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(RTP_Import.promote_Treatment_Plan_Dialog) is not None else False

def __find_group_edits_of_fields_dialog() -> bool:
    """Searches for the Group Edits of Fields dialog within the RTP Import workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the rtp_import.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(RTP_Import.group_Edit_of_Fields_dialog) is not None else False

def __find_delete_move_dialog() -> bool:
    """Searches for the Delete/Move Imported File dialog within the RTP Import workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the rtp_import.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(RTP_Import.delete_Move_Imported_File_Dialog) is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_rtp_import_select_button() -> None:
    """Locates the RTP Import UI window and clicks the Select button.
    """
    if __find_main_window():
        CommonActions.left_click_object(RTP_Import.Select_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_rtp_import_close_button() -> None:
    """Locates the RTP Import UI window and clicks the Close button.
    """
    if __find_main_window():
        CommonActions.left_click_object(RTP_Import.Close_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_tree_item_treatment_fields() -> None:
    """Locates the Promote Plan UI window and clicks the Treatment Fields tree item from the list view object.
    """
    if __find_promote_plan_window():
        CommonActions.find_object(RTP_Import.promote_Treatment_Plan_Tree)
        CommonActions.left_click_object(RTP_Import.promote_Treatment_Plan_Tree_Treatment_Fields)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_promote_plan_field_groups_button() -> None:
    """Locates the Promote Plan UI window and clicks the Field Group button and finds the Group Edit of Fields Dialog.
    """
    if __find_promote_plan_window():
        CommonActions.left_click_object(RTP_Import.promote_Treatment_Plan_Field_Group_Button)
        CommonActions.find_object(RTP_Import.group_Edit_of_Fields_dialog_Site_Name_ComboBox_Item)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_first_site_name_in_edit_fields_dialog() -> None:
    """Locates the Promote Plan UI window and selects the first site name option from the Site Name Combo Box object.
    """
    if __find_group_edits_of_fields_dialog():
        CommonActions.left_click_object(RTP_Import.group_Edit_of_Fields_dialog_Site_Name_ComboBox)
        CommonActions.left_click_object(RTP_Import.group_Edit_of_Fields_dialog_Site_Name_ComboBox_Item)
        CommonActions.find_object(RTP_Import.group_Edit_of_Fields_dialog)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_clinical_tolerance_in_edit_fields_dialog() -> None:
    """Locates the Promote Plan UI window and selects the Clinical tolerance option from the Tolerance Table Combo Box object.
    """
    if __find_group_edits_of_fields_dialog():
        CommonActions.left_click_object(RTP_Import.group_Edit_of_Fields_dialog_Tolerance_Table_ComboBox)
        CommonActions.left_click_object(RTP_Import.group_Edit_of_Fields_dialog_ComboBox_Item_Clinical)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_edit_in_fields_OK_button() -> None:
    """Locates the Promote Plan UI window and selects the OK button object.
    """
    if __find_group_edits_of_fields_dialog():
        CommonActions.left_click_object(RTP_Import.group_Edit_of_Fields_dialog_OK_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_promote_plan_promote_button() -> None:
    """Locates the Promote Plan UI window and clicks the Promote button object.
    """
    if __find_promote_plan_window():
        CommonActions.left_click_object(RTP_Import.promote_Treatment_Plan_Promote_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_yes_button_in_delete_move_dialog() -> None:
    """Locates the Delete/Move Imported File dialog and clicks the Yes button object.
    """
    if __find_delete_move_dialog():
        CommonActions.left_click_object(RTP_Import.delete_Move_Imported_File_Yes_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_no_button_in_delete_move_dialog() -> None:
    """Locates the Delete/Move Imported File dialog and clicks the Yes button object.
    """
    if __find_delete_move_dialog():
        CommonActions.left_click_object(RTP_Import.delete_Move_Imported_File_No_Button)